function coverageSummary(entries){
 const scripts=new Map();
 for(const entry of entries){
  if(!entry.url.startsWith(base)||!entry.url.endsWith('.mjs')||typeof entry.source!=='string')continue;
  const ranges=entry.functions.flatMap(fn=>fn.ranges),boundaries=[...new Set([0,entry.source.length,...ranges.flatMap(range=>[range.startOffset,range.endOffset])])].sort((a,b)=>a-b),spans=[];
  for(let index=0;index<boundaries.length-1;index++){
   const start=boundaries[index],end=boundaries[index+1],covering=ranges.filter(range=>range.startOffset<=start&&range.endOffset>=end);
   if(!covering.length)continue;
   const smallest=Math.min(...covering.map(range=>range.endOffset-range.startOffset));
   if(covering.some(range=>range.endOffset-range.startOffset===smallest&&range.count>0))spans.push([start,end]);
  }
  const existing=scripts.get(entry.url);assert.ok(!existing||existing.source===entry.source,'source must remain stable during coverage collection');scripts.set(entry.url,{source:entry.source,spans:[...(existing?.spans||[]),...spans]});
 }
 const files=[...scripts].map(([url,{source,spans}])=>{
  const merged=[];for(const span of spans.sort((a,b)=>a[0]-b[0])){const previous=merged.at(-1);if(previous&&span[0]<=previous[1])previous[1]=Math.max(previous[1],span[1]);else merged.push([...span]);}
  const totalBytes=Buffer.byteLength(source,'utf8'),executedBytes=merged.reduce((sum,[start,end])=>sum+Buffer.byteLength(source.slice(start,end),'utf8'),0);return {url,totalBytes,executedBytes,percent:Number((executedBytes/totalBytes*100).toFixed(2)),executedRanges:merged};
 });
 return {method:'V8 innermost ranges, union across navigations, UTF-8 bytes; browser flows only',files,totalBytes:files.reduce((sum,file)=>sum+file.totalBytes,0),executedBytes:files.reduce((sum,file)=>sum+file.executedBytes,0)};
}

